<template>
  <div class="registration-admin"><header><RouterLink to="/admin-dashboard">← 返回管理员工作台</RouterLink><h1>球员学籍审核</h1><p>每名球员每赛季审核一次基础学籍资格；各赛事球队参赛规则在整队报名时另审。</p><RouterLink to="/admin-seasons">管理赛季及注册窗口 →</RouterLink></header>
    <div v-if="error" class="notice error" role="alert">{{ error }}</div><div v-if="success" class="notice success" role="status">{{ success }}</div>
    <form class="filters" @submit.prevent="search"><label>查看赛季<select v-model="seasonId" :disabled="saving"><option value="">当前启用赛季</option><option v-for="s in seasons" :key="s.id" :value="String(s.id)">{{ s.season_name }}</option></select></label><label>申请状态<select v-model="status" :disabled="saving"><option value="">全部状态</option><option v-for="(label,value) in labels" :key="value" :value="value">{{ label }}</option></select></label><label>搜索球员<input v-model="query" placeholder="姓名、学号或学院" maxlength="100" :disabled="saving"></label><button :disabled="loading || saving">查询</button></form>
    <div class="summary"><span v-for="(label,value) in labels" :key="value">{{ label }} <strong>{{ summary[value] || 0 }}</strong></span></div>
    <div class="table-wrap"><table><thead><tr><th>姓名</th><th>当前学号</th><th>学院</th><th>状态</th><th>最近提交</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.account.name }}</td><td>{{ item.account.student_id }}</td><td>{{ item.account.college }}</td><td>{{ labels[item.status] }}{{ item.account.is_active ? '' : ' · 账号已停用' }}</td><td>{{ time(item.submitted_at) }}</td><td><button :disabled="saving" @click="open(item.id)">查看申请</button></td></tr><tr v-if="!items.length"><td colspan="6">{{ loading ? '正在加载…' : '暂无符合条件的申请' }}</td></tr></tbody></table></div>
    <div class="pagination"><span>共 {{ pagination.total }} 份申请 · 第 {{ page }} 页</span><button :disabled="page <= 1 || loading || saving" @click="page--; load()">上一页</button><button :disabled="page >= pagination.total_pages || loading || saving" @click="page++; load()">下一页</button></div>
    <section v-if="detail" class="detail"><div class="detail-heading"><h2>{{ detail.account.name }} · {{ detail.season.season_name }}</h2><div><button :disabled="saving" @click="open(detail.registration.id)">刷新申请详情</button><button :disabled="saving" @click="close">关闭详情</button></div></div><p>当前状态：<strong>{{ labels[detail.registration.status] }}</strong></p>
      <div class="profile-comparison"><div><h3>提交时资料</h3><p>姓名：{{ detail.registration.profile_snapshot.name }}</p><p>学号：{{ detail.registration.profile_snapshot.student_id }}</p><p>学院：{{ detail.registration.profile_snapshot.college }}</p></div><div><h3>账号最新资料</h3><p>姓名：{{ detail.account.name }}</p><p>学号：{{ detail.account.student_id }}</p><p>学院：{{ detail.account.college }}</p><p v-if="!detail.account.is_active" class="disabled-account">账号已停用，不能通过审核。</p></div></div>
      <div v-if="detail.registration.return_reason" class="notice">上次审核说明：{{ detail.registration.return_reason }}</div>
      <label v-if="detail.files.length > 1">学籍截图版本<select v-model="fileId"><option v-for="file in detail.files" :key="file.id" :value="file.id">提交版本 {{ file.revision }} · {{ time(file.created_at) }}</option></select></label>
      <PlayerAcademicImage v-if="chosenFile?.available" :registration-id="detail.registration.id" :file-id="chosenFile.id"/><p v-else>材料已清理或尚未提供。</p>
      <div v-if="detail.season.is_active && ['pending','approved'].includes(detail.registration.status)" v-draft="{ value: reason, resetKey: detail?.registration.id }" class="review-controls"><label>审核说明／退回或撤销原因<textarea v-model="reason" rows="3" maxlength="500" placeholder="退回、撤销资格时必须填写原因" :disabled="saving"></textarea></label><p class="help">通过审核可不填说明；退回或撤销后，球员可以在截止后补正并重新提交。</p><div class="actions"><template v-if="detail.registration.status === 'pending'"><button class="primary" :disabled="saving || !detail.account.is_active || !detail.files[0]?.available" @click="review('approve')">通过审核</button><button :disabled="saving" @click="review('return')">退回补正</button></template><button v-else class="danger" :disabled="saving" @click="review('revoke')">撤销当季资格</button></div></div><p v-else-if="!detail.season.is_active" class="help">该赛季当前未启用，申请只读。</p>
      <details class="history" open><summary>申请操作记录（最近100条）</summary><ol><li v-for="event in detail.events" :key="event.id"><strong>{{ operations[event.operation] || event.operation }}</strong> · {{ time(event.created_at) }} · {{ event.actor_admin_id ? '管理员 #' + event.actor_admin_id : '球员本人' }}<p v-if="event.reason">{{ event.reason }}</p><p>本次材料资料：{{ event.after_snapshot.profile_snapshot.name }} / {{ event.after_snapshot.profile_snapshot.student_id }} / {{ event.after_snapshot.profile_snapshot.college }}</p><p v-if="event.after_snapshot.review_profile_snapshot">审核时账号：{{ event.after_snapshot.review_profile_snapshot.name }} / {{ event.after_snapshot.review_profile_snapshot.student_id }} / {{ event.after_snapshot.review_profile_snapshot.college }}</p></li></ol></details>
    </section>
  </div>
</template>
<script setup>
import { confirmDraftLeave } from '../../../shared-ui/interaction.js'
import { ref, computed, onMounted } from 'vue'
import api from '../api/http'
import PlayerAcademicImage from '../components/PlayerAcademicImage.vue'
const seasons = ref([]), seasonId = ref(''), status = ref('pending'), query = ref(''), page = ref(1), items = ref([]), summary = ref({}), pagination = ref({ total: 0, total_pages: 0 }), detail = ref(null), fileId = ref(null), reason = ref(''), loading = ref(false), saving = ref(false), error = ref(''), success = ref('')
const labels = { pending: '待审核', approved: '已通过', returned: '已退回', withdrawn: '已撤回', revoked: '已撤销' }, operations = { submitted: '提交截图', approved: '审核通过', returned: '退回补正', withdrawn: '本人撤回', revoked: '撤销资格' }
const time = value => value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : '—'
const chosenFile = computed(() => detail.value?.files.find(f => f.id === fileId.value)); let sequence = 0, detailSequence = 0
function fail(e) { error.value = e.response?.data?.message || '操作失败，请重试' }
function assign(value) { detail.value = value; fileId.value = value.files[0]?.id || null; reason.value = '' }
async function load() { const current = ++sequence; loading.value = true; try { const r = await api.get('/player-admin/season-registrations', { params: { season_id: seasonId.value || undefined, status: status.value, q: query.value, page: page.value } }); if (current === sequence) { items.value = r.data.items; summary.value = r.data.summary; pagination.value = r.data.pagination } } catch(e) { fail(e) } finally { if (current === sequence) loading.value = false } }
function search() {if(!confirmDraftLeave(document.querySelector('.review-controls')))return; page.value = 1; error.value = ''; close(); load() }
function close() {if(!confirmDraftLeave(document.querySelector('.review-controls')))return; detailSequence++; detail.value = null; reason.value = ''; success.value = '' }
async function open(id) {if(!confirmDraftLeave(document.querySelector('.review-controls')))return; const current = ++detailSequence; detail.value = null; error.value = ''; success.value = ''; try { const r = await api.get(`/player-admin/season-registrations/${id}`); if (current === detailSequence) assign(r.data) } catch(e) { fail(e) } }
async function review(action) { saving.value = true; error.value = ''; success.value = ''; try { const data = { reason: reason.value }; if (action === 'approve') data.account_revision = detail.value.account.revision; const r = await api.post(`/player-admin/season-registrations/${detail.value.registration.id}/${action}`, data, { headers: { 'If-Match': String(detail.value.registration.revision) } }); assign(r.data); success.value = { approve: '审核已通过。', return: '申请已退回，球员可以补正重提。', revoke: '当季资格已撤销，相关站内提示已生成。' }[action]; await load() } catch(e) { fail(e) } finally { saving.value = false } }
onMounted(async () => { try { seasons.value = (await api.get('/season')).data; await load() } catch(e) { fail(e) } })
</script>
<style scoped>
@layer legacy {

.registration-admin{max-width:1200px;padding:32px 24px;margin:auto;color:#243c55}.registration-admin a{color:#2564a5}header h1{font-size:28px;margin:18px 0 12px}header p,.help{font-size:14px;color:#718398}.filters{display:flex;flex-wrap:wrap;align-items:flex-end;gap:16px;margin:26px 0}.registration-admin label{display:block;font-weight:600;font-size:14px}.registration-admin input,.registration-admin select,.registration-admin textarea{display:block;box-sizing:border-box;width:100%;padding:10px 12px;font:inherit;border:1px solid #cbd8e7;border-radius:6px;margin-top:7px}.registration-admin button{width:auto;background:white;color:#285d9b;border:1px solid #c7d7e9;border-radius:6px;padding:9px 15px;font:inherit;cursor:pointer}.registration-admin button:disabled{opacity:.5;cursor:wait}.summary{display:flex;flex-wrap:wrap;gap:22px;padding:16px;background:#edf3fa;border-radius:9px;margin-bottom:20px;font-size:14px}.summary strong{margin-left:8px}.table-wrap{overflow:auto;border:1px solid #dce5ef;border-radius:9px;background:white}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:14px;border-bottom:1px solid #e5ecf3}th{font-size:14px;background:#f3f6fa}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:14px;margin:20px 0;font-size:14px}.detail{padding:28px;background:white;border:1px solid #dce5ef;border-radius:12px}.detail-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.detail-heading h2{font-size:22px}.detail-heading button{margin-left:10px}.profile-comparison{display:grid;grid-template-columns:1fr 1fr;gap:24px;background:#f3f7fb;padding:20px;margin:20px 0;border-radius:8px}.profile-comparison h3{font-size:16px}.profile-comparison p{font-size:14px;overflow-wrap:anywhere}.notice{padding:14px;background:#fff6e8;border-radius:7px;margin:18px 0;white-space:pre-wrap}.notice.error{background:#fff0ef;color:#a32e25}.notice.success{background:#eaf6ef;color:#286442}.review-controls{margin:26px 0}.actions{display:flex;gap:14px}.registration-admin .primary{background:#285fa5;color:white}.registration-admin .danger{background:white;border-color:#d9afa7;color:#a23d30}.history{margin-top:28px;font-size:14px}.history summary{cursor:pointer}.history li{padding:12px 0;border-bottom:1px solid #e8edf4}.history p{margin:8px 0;color:#708298;white-space:pre-wrap}.detail>label{margin-bottom:20px}.disabled-account{color:#a32e25}@media(max-width:650px){.registration-admin{padding:24px 15px}.filters{align-items:stretch;flex-direction:column}.profile-comparison{grid-template-columns:1fr;gap:8px}.detail{padding:18px}.detail-heading{flex-direction:column;align-items:flex-start}.detail-heading button{margin:0 10px 10px 0}.pagination{gap:9px}.history ol{padding-left:20px}}

}
</style>
